PRAGMA journal_mode=WAL;
CREATE TABLE IF NOT EXISTS models(id INTEGER PRIMARY KEY, name TEXT NOT NULL, family TEXT NOT NULL, status TEXT NOT NULL, metadata_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS datasets(id TEXT PRIMARY KEY, name TEXT NOT NULL, source TEXT NOT NULL, status TEXT NOT NULL, record_count INTEGER NOT NULL, metadata_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sequences(id TEXT PRIMARY KEY, dataset_id TEXT NOT NULL REFERENCES datasets(id), species TEXT NOT NULL, split TEXT NOT NULL, label TEXT NOT NULL, sequence TEXT NOT NULL, sha256 TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS runs(id INTEGER PRIMARY KEY, kind TEXT NOT NULL, status TEXT NOT NULL, result_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
